7	/**
8	 * @fileoverview Defines the core configuration interfaces and types for the agent architecture.
9	 */
10	
11	import type { Content, FunctionDeclaration } from '@google/genai';
12	import type { AnyDeclarativeTool } from '../tools/tools.js';
13	import { type z } from 'zod';
14	import type { ModelConfig } from '../services/modelConfigService.js';
15	import type { AnySchema } from 'ajv';
16	import type { A2AAuthConfig } from './auth-provider/types.js';
17	import type { MCPServerConfig } from '../config/config.js';
18	
19	/**
20	 * Describes the possible termination modes for an agent.
21	 */
22	export enum AgentTerminateMode {
23	  ERROR = 'ERROR',
24	  TIMEOUT = 'TIMEOUT',
25	  GOAL = 'GOAL',
26	  MAX_TURNS = 'MAX_TURNS',
27	  ABORTED = 'ABORTED',
28	  ERROR_NO_COMPLETE_TASK_CALL = 'ERROR_NO_COMPLETE_TASK_CALL',
29	}
30	
31	/**
32	 * Represents the output structure of an agent's execution.
33	 */
34	export interface OutputObject {
35	  result: string;
36	  terminate_reason: AgentTerminateMode;
37	}
38	
39	/**
40	 * The default query string provided to an agent as input.
41	 */
42	export const DEFAULT_QUERY_STRING = 'Get Started!';
43	
44	/**
45	 * The default maximum number of conversational turns for an agent.
46	 */
47	export const DEFAULT_MAX_TURNS = 30;
48	
49	/**
50	 * The default maximum execution time for an agent in minutes.
51	 */
52	export const DEFAULT_MAX_TIME_MINUTES = 10;
53	
54	/**
55	 * Represents the validated input parameters passed to an agent upon invocation.
56	 * Used primarily for templating the system prompt. (Replaces ContextState)
57	 */
58	export type AgentInputs = Record<string, unknown>;
59	
60	/**
61	 * Simplified input structure for Remote Agents, which consumes a single string query.
62	 */
63	export type RemoteAgentInputs = { query: string };
64	
65	/**
66	 * Structured events emitted during subagent execution for user observability.
67	 */
68	export enum SubagentActivityErrorType {
69	  REJECTED = 'REJECTED',
70	  CANCELLED = 'CANCELLED',
71	  GENERIC = 'GENERIC',
72	}
73	
74	/**
75	 * Standard error messages for subagent activities.
76	 */
77	export const SUBAGENT_REJECTED_ERROR_PREFIX = 'User rejected this operation.';
78	export const SUBAGENT_CANCELLED_ERROR_MESSAGE = 'Request cancelled.';
79	
80	export interface SubagentActivityEvent {
81	  isSubagentActivityEvent: true;
82	  agentName: string;
83	  type: 'TOOL_CALL_START' | 'TOOL_CALL_END' | 'THOUGHT_CHUNK' | 'ERROR';
84	  data: Record<string, unknown>;
85	}
86	
87	export interface SubagentActivityItem {
88	  id: string;
89	  type: 'thought' | 'tool_call';
90	  content: string;
91	  displayName?: string;
92	  description?: string;
93	  args?: string;
94	  status: 'running' | 'completed' | 'error' | 'cancelled';
95	}
96	
97	export interface SubagentProgress {
98	  isSubagentProgress: true;
99	  agentName: string;
100	  recentActivity: SubagentActivityItem[];
101	  state?: 'running' | 'completed' | 'error' | 'cancelled';
102	  result?: string;
103	  terminateReason?: AgentTerminateMode;
104	}
105	
106	export function isSubagentProgress(obj: unknown): obj is SubagentProgress {
107	  return (
108	    typeof obj === 'object' &&
109	    obj !== null &&
110	    'isSubagentProgress' in obj &&
111	    obj.isSubagentProgress === true
112	  );
113	}
114	
115	/**
116	 * Checks if the tool call data indicates an error.
117	 */
118	export function isToolActivityError(data: unknown): boolean {
119	  return (
120	    data !== null &&
121	    typeof data === 'object' &&
122	    'isError' in data &&
123	    data.isError === true
124	  );
125	}
126	
127	/**
128	 * The base definition for an agent.
129	 * @template TOutput The specific Zod schema for the agent's final output object.
130	 */
131	export interface BaseAgentDefinition<
132	  TOutput extends z.ZodTypeAny = z.ZodUnknown,
133	> {
134	  /** Unique identifier for the agent. */
135	  name: string;
136	  displayName?: string;
137	  description: string;
138	  experimental?: boolean;
139	  inputConfig: InputConfig;
140	  outputConfig?: OutputConfig<TOutput>;
141	  metadata?: {
142	    hash?: string;
143	    filePath?: string;
144	  };
145	}
146	
147	export interface LocalAgentDefinition<
148	  TOutput extends z.ZodTypeAny = z.ZodUnknown,
149	> extends BaseAgentDefinition<TOutput> {
150	  kind: 'local';
151	
152	  // Local agent required configs
153	  promptConfig: PromptConfig;
154	  modelConfig: ModelConfig;
155	  runConfig: RunConfig;
156	
157	  // Optional configs
158	  toolConfig?: ToolConfig;
159	
160	  /**
161	   * Optional inline MCP servers for this agent.
162	   */
163	  mcpServers?: Record<string, MCPServerConfig>;
164	
165	  /**
166	   * An optional function to process the raw output from the agent's final tool
167	   * call into a string format.
168	   *
169	   * @param output The raw output value from the `complete_task` tool, now strongly typed with TOutput.
170	   * @returns A string representation of the final output.
171	   */
172	  processOutput?: (output: z.infer<TOutput>) => string;
173	}
174	
175	export interface RemoteAgentDefinition<
176	  TOutput extends z.ZodTypeAny = z.ZodUnknown,
177	> extends BaseAgentDefinition<TOutput> {
178	  kind: 'remote';
179	  agentCardUrl: string;
180	  /** The user-provided description, before any remote card merging. */
181	  originalDescription?: string;
182	  /**
183	   * Optional authentication configuration for the remote agent.
184	   * If not specified, the agent will try to use defaults based on the AgentCard's
185	   * security requirements.
186	   */
187	  auth?: A2AAuthConfig;
188	}
189	
190	export type AgentDefinition<TOutput extends z.ZodTypeAny = z.ZodUnknown> =
191	  | LocalAgentDefinition<TOutput>
192	  | RemoteAgentDefinition<TOutput>;
193	
194	/**
195	 * Configures the initial prompt for the agent.
196	 */
197	export interface PromptConfig {
198	  /**
199	   * A single system prompt string. Supports templating using `${input_name}` syntax.
200	   */
201	  systemPrompt?: string;
202	  /**
203	   * An array of user/model content pairs for few-shot prompting.
204	   */
205	  initialMessages?: Content[];
206	
207	  /**
208	   * The specific task or question to trigger the agent's execution loop.
209	   * This is sent as the first user message, distinct from the systemPrompt (identity/rules)
210	   * and initialMessages (history/few-shots). Supports templating.
211	   * If not provided, a generic "Get Started!" message is used.
212	   */
213	  query?: string;
214	}
215	
216	/**
217	 * Configures the tools available to the agent during its execution.
218	 */
219	export interface ToolConfig {
220	  tools: Array<string | FunctionDeclaration | AnyDeclarativeTool>;
221	}
222	
223	/**
224	 * Configures the expected inputs (parameters) for the agent.
225	 */
226	export interface InputConfig {
227	  inputSchema: AnySchema;
228	}
229	
230	/**
231	 * Configures the expected outputs for the agent.
232	 */
233	export interface OutputConfig<T extends z.ZodTypeAny> {
234	  /**
235	   * The name of the final result parameter. This will be the name of the
236	   * argument in the `submit_final_output` tool (e.g., "report", "answer").
237	   */
238	  outputName: string;
239	  /**
240	   * A description of the expected output. This will be used as the description
241	   * for the tool argument.
242	   */
243	  description: string;
244	  /**
245	   * Optional JSON schema for the output. If provided, it will be used as the
246	   * schema for the tool's argument, allowing for structured output enforcement.
247	   * Defaults to { type: 'string' }.
248	   */
249	  schema: T;
250	}
251	
252	/**
253	 * Configures the execution environment and constraints for the agent.
254	 */
255	export interface RunConfig {
256	  /**
257	   * The maximum execution time for the agent in minutes.
258	   * If not specified, defaults to DEFAULT_MAX_TIME_MINUTES (10).
259	   */
260	  maxTimeMinutes
