7	import { load } from 'js-yaml';
8	import * as fs from 'node:fs/promises';
9	import { type Dirent } from 'node:fs';
10	import * as path from 'node:path';
11	import * as crypto from 'node:crypto';
12	import { z } from 'zod';
13	import {
14	  type AgentDefinition,
15	  DEFAULT_MAX_TURNS,
16	  DEFAULT_MAX_TIME_MINUTES,
17	} from './types.js';
18	import type { A2AAuthConfig } from './auth-provider/types.js';
19	import { MCPServerConfig } from '../config/config.js';
20	import { isValidToolName } from '../tools/tool-names.js';
21	import { FRONTMATTER_REGEX } from '../skills/skillLoader.js';
22	import { getErrorMessage } from '../utils/errors.js';
23	
24	/**
25	 * Error thrown when an agent definition is invalid or cannot be loaded.
26	 */
27	export class AgentLoadError extends Error {
28	  constructor(
29	    public filePath: string,
30	    message: string,
31	  ) {
32	    super(`Failed to load agent from ${filePath}: ${message}`);
33	    this.name = 'AgentLoadError';
34	  }
35	}
36	
37	/**
38	 * Result of loading agents from a directory.
39	 */
40	export interface AgentLoadResult {
41	  agents: AgentDefinition[];
42	  errors: AgentLoadError[];
43	}
44	
45	const nameSchema = z
46	  .string()
47	  .regex(/^[a-z0-9-_]+$/, 'Name must be a valid slug');
48	
49	const mcpServerSchema = z.object({
50	  command: z.string().optional(),
51	  args: z.array(z.string()).optional(),
52	  env: z.record(z.string()).optional(),
53	  cwd: z.string().optional(),
54	  url: z.string().optional(),
55	  http_url: z.string().optional(),
56	  headers: z.record(z.string()).optional(),
57	  tcp: z.string().optional(),
58	  type: z.enum(['sse', 'http']).optional(),
59	  timeout: z.number().optional(),
60	  trust: z.boolean().optional(),
61	  description: z.string().optional(),
62	  include_tools: z.array(z.string()).optional(),
63	  exclude_tools: z.array(z.string()).optional(),
64	});
65	
66	const localAgentSchema = z
67	  .object({
68	    kind: z.literal('local').optional().default('local'),
69	    name: nameSchema,
70	    description: z.string().min(1),
71	    display_name: z.string().optional(),
72	    tools: z
73	      .array(
74	        z
75	          .string()
76	          .refine((val) => isValidToolName(val, { allowWildcards: true }), {
77	            message: 'Invalid tool name',
78	          }),
79	      )
80	      .optional(),
81	    mcp_servers: z.record(mcpServerSchema).optional(),
82	    model: z.string().optional(),
83	    temperature: z.number().optional(),
84	    max_turns: z.number().int().positive().optional(),
85	    timeout_mins: z.number().int().positive().optional(),
86	  })
87	  .strict();
88	
89	type FrontmatterLocalAgentDefinition = z.infer<typeof localAgentSchema> & {
90	  system_prompt: string;
91	};
92	
93	// Base fields shared by all auth configs.
94	const baseAuthFields = {};
95	
96	const apiKeyAuthSchema = z.object({
97	  ...baseAuthFields,
98	  type: z.literal('apiKey'),
99	  key: z.string().min(1, 'API key is required'),
100	  name: z.string().optional(),
101	});
102	
103	const httpAuthSchema = z.object({
104	  ...baseAuthFields,
105	  type: z.literal('http'),
106	  scheme: z.string().min(1),
107	  token: z.string().min(1).optional(),
108	  username: z.string().min(1).optional(),
109	  password: z.string().min(1).optional(),
110	  value: z.string().min(1).optional(),
111	});
112	
113	const googleCredentialsAuthSchema = z.object({
114	  ...baseAuthFields,
115	  type: z.literal('google-credentials'),
116	  scopes: z.array(z.string()).optional(),
117	});
118	
119	const oauth2AuthSchema = z.object({
120	  ...baseAuthFields,
121	  type: z.literal('oauth'),
122	  client_id: z.string().optional(),
123	  client_secret: z.string().optional(),
124	  scopes: z.array(z.string()).optional(),
125	  authorization_url: z.string().url().optional(),
126	  token_url: z.string().url().optional(),
127	});
128	
129	const authConfigSchema = z
130	  .discriminatedUnion('type', [
131	    apiKeyAuthSchema,
132	    httpAuthSchema,
133	    googleCredentialsAuthSchema,
134	    oauth2AuthSchema,
135	  ])
136	  .superRefine((data, ctx) => {
137	    if (data.type === 'http') {
138	      if (data.value) return;
139	      if (data.scheme === 'Bearer') {
140	        if (!data.token) {
141	          ctx.addIssue({
142	            code: z.ZodIssueCode.custom,
143	            message: 'Bearer scheme requires "token"',
144	            path: ['token'],
145	          });
146	        }
147	      } else if (data.scheme === 'Basic') {
148	        if (!data.username) {
149	          ctx.addIssue({
150	            code: z.ZodIssueCode.custom,
151	            message: 'Basic authentication requires "username"',
152	            path: ['username'],
153	          });
154	        }
155	        if (!data.password) {
156	          ctx.addIssue({
157	            code: z.ZodIssueCode.custom,
158	            message: 'Basic authentication requires "password"',
159	            path: ['password'],
160	          });
161	        }
162	      } else {
163	        ctx.addIssue({
164	          code: z.ZodIssueCode.custom,
165	          message: `HTTP scheme "${data.scheme}" requires "value"`,
166	          path: ['value'],
167	        });
168	      }
169	    }
170	  });
171	
172	type FrontmatterAuthConfig = z.infer<typeof authConfigSchema>;
173	
174	const remoteAgentSchema = z
175	  .object({
176	    kind: z.literal('remote').optional().default('remote'),
177	    name: nameSchema,
178	    description: z.string().optional(),
179	    display_name: z.string().optional(),
180	    agent_card_url: z.string().url(),
181	    auth: authConfigSchema.optional(),
182	  })
183	  .strict();
184	
185	type FrontmatterRemoteAgentDefinition = z.infer<typeof remoteAgentSchema>;
186	
187	type FrontmatterAgentDefinition =
188	  | FrontmatterLocalAgentDefinition
189	  | FrontmatterRemoteAgentDefinition;
190	
191	const agentUnionOptions = [
192	  { schema: localAgentSchema, label: 'Local Agent' },
193	  { schema: remoteAgentSchema, label: 'Remote Agent' },
194	] as const;
195	
196	const remoteAgentsListSchema = z.array(remoteAgentSchema);
197	
198	const markdownFrontmatterSchema = z.union([
199	  agentUnionOptions[0].schema,
200	  agentUnionOptions[1].schema,
201	]);
202	
203	function guessIntendedKind(rawInput: unknown): 'local' | 'remote' | undefined {
204	  if (typeof rawInput !== 'object' || rawInput === null) return undefined;
205	  const input = rawInput as Partial<FrontmatterLocalAgentDefinition> &
206	    Partial<FrontmatterRemoteAgentDefinition>;
207	
208	  if (input.kind === 'local') return 'local';
209	  if (input.kind === 'remote') return 'remote';
210	
211	  const hasLocalKeys =
212	    'tools' in input ||
213	    'mcp_servers' in input ||
214	    'model' in input ||
215	    'temperature' in input ||
